static void volvoxai_v1_create_execution_context_request_clear_execution(
    VolvoxaiV1CreateExecutionContextRequest* message) {
    const SynurangLiteAllocator* allocator =
        synurang_lite_allocator_or_default(message->_allocator);
    (void)allocator; /* Scalar-only oneofs own no allocations. */
    switch (message->which_execution) {
        case 2:
            if (message->field_graph) {
                volvoxai_v1_graph_execution_free(message->field_graph);
                synurang_lite_release(allocator, message->field_graph);
                message->field_graph = NULL;
            }
            break;
        case 3:
            if (message->field_autoregressive) {
                volvoxai_v1_autoregressive_execution_free(message->field_autoregressive);
                synurang_lite_release(allocator, message->field_autoregressive);
                message->field_autoregressive = NULL;
            }
            break;
        default: break;
    }
    message->which_execution = 0;
}
static void volvoxai_v1_create_tokenizer_request_clear_vocabulary(
    VolvoxaiV1CreateTokenizerRequest* message) {
    const SynurangLiteAllocator* allocator =
        synurang_lite_allocator_or_default(message->_allocator);
    (void)allocator; /* Scalar-only oneofs own no allocations. */
    switch (message->which_vocabulary) {
        case 1:
            if (message->field_tokens) {
                volvoxai_v1_tokenizer_vocabulary_free(message->field_tokens);
                synurang_lite_release(allocator, message->field_tokens);
                message->field_tokens = NULL;
            }
            break;
        case 2:
            synurang_lite_bytes_clear(allocator, &message->field_vocabulary_json);
            break;
        case 3:
            synurang_lite_bytes_clear(allocator, &message->field_vocabulary_binary);
            break;
        case 5:
            if (message->field_byte_level) {
                volvoxai_v1_byte_level_tokenizer_vocabulary_free(message->field_byte_level);
                synurang_lite_release(allocator, message->field_byte_level);
                message->field_byte_level = NULL;
            }
            break;
        case 6:
            synurang_lite_bytes_clear(allocator, &message->field_hugging_face_tokenizer_json);
            break;
        default: break;
    }
    message->which_vocabulary = 0;
}
