const char* volvoxai_v1_observation_status_name(VolvoxaiV1ObservationStatus value) {
    switch (value) {
        case VOLVOXAI_V1_OBSERVATION_STATUS_UNSPECIFIED: return "OBSERVATION_STATUS_UNSPECIFIED";
        case VOLVOXAI_V1_OBSERVATION_STATUS_AVAILABLE: return "OBSERVATION_STATUS_AVAILABLE";
        case VOLVOXAI_V1_OBSERVATION_STATUS_UNSUPPORTED: return "OBSERVATION_STATUS_UNSUPPORTED";
        case VOLVOXAI_V1_OBSERVATION_STATUS_NOT_COLLECTED: return "OBSERVATION_STATUS_NOT_COLLECTED";
        case VOLVOXAI_V1_OBSERVATION_STATUS_FAILED: return "OBSERVATION_STATUS_FAILED";
        default: return NULL;
    }
}

int volvoxai_v1_observation_status_parse(const char* name, VolvoxaiV1ObservationStatus* value) {
    if (!name || !value) return 0;
    if (strcmp(name, "OBSERVATION_STATUS_UNSPECIFIED") == 0) {
        *value = VOLVOXAI_V1_OBSERVATION_STATUS_UNSPECIFIED;
        return 1;
    }
    if (strcmp(name, "OBSERVATION_STATUS_AVAILABLE") == 0) {
        *value = VOLVOXAI_V1_OBSERVATION_STATUS_AVAILABLE;
        return 1;
    }
    if (strcmp(name, "OBSERVATION_STATUS_UNSUPPORTED") == 0) {
        *value = VOLVOXAI_V1_OBSERVATION_STATUS_UNSUPPORTED;
        return 1;
    }
    if (strcmp(name, "OBSERVATION_STATUS_NOT_COLLECTED") == 0) {
        *value = VOLVOXAI_V1_OBSERVATION_STATUS_NOT_COLLECTED;
        return 1;
    }
    if (strcmp(name, "OBSERVATION_STATUS_FAILED") == 0) {
        *value = VOLVOXAI_V1_OBSERVATION_STATUS_FAILED;
        return 1;
    }
    return 0;
}


