static SynurangLiteStatus volvoxai_v1_autoregressive_execution_merge_reader(
    VolvoxaiV1AutoregressiveExecution* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
                if (!sl_read_enum(
                        reader, wire_type, &message->field_sampling)) break;
                break;
            case 2:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_max_steps)) break;
                break;
            case 3:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_seed)) break;
                message->has_seed = 1;
                break;
            case 4:
            {
                void* appended;
                if (wire_type == 2) {
                    const uint8_t* packed_data;
                    size_t packed_len;
                    SynurangLiteReaderInternal packed;
                    if (!sl_read_slice(reader, &packed_data, &packed_len)) break;
                    sl_reader_init(&packed, packed_data, packed_len);
                    while (packed.pos < packed.len) {
                        status = sl_array_append(
                            message->_allocator,
                            (void**)&message->field_stop_ids.data,
                            &message->field_stop_ids.len,
                            &message->field_stop_ids.cap,
                            sizeof(*message->field_stop_ids.data),
                            &appended);
                        if (status != SYNURANG_LITE_OK) return status;
                        if (!sl_read_int32_raw(
                                &packed,
                                (int32_t*)appended)) break;
                    }
                    if (packed.status != SYNURANG_LITE_OK || packed.pos != packed.len) {
                        reader->status = packed.status == SYNURANG_LITE_OK
                            ? SYNURANG_LITE_MALFORMED : packed.status;
                    }
                } else {
                    status = sl_array_append(
                        message->_allocator,
                        (void**)&message->field_stop_ids.data,
                        &message->field_stop_ids.len,
                        &message->field_stop_ids.cap,
                        sizeof(*message->field_stop_ids.data),
                        &appended);
                    if (status != SYNURANG_LITE_OK) return status;
                    if (!sl_read_int32(
                            reader,
                            wire_type,
                            (int32_t*)appended)) break;
                }
                break;
            }
            case 5:
            {
                const uint8_t* value_data;
                size_t value_len;
                VolvoxaiV1IdStopSequence* item;
                void* appended;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = sl_array_append(
                    message->_allocator,
                    (void**)&message->field_stop_sequences.data,
                    &message->field_stop_sequences.len,
                    &message->field_stop_sequences.cap,
                    sizeof(*message->field_stop_sequences.data),
                    &appended);
                if (status != SYNURANG_LITE_OK) return status;
                item = (VolvoxaiV1IdStopSequence*)appended;
                volvoxai_v1_id_stop_sequence_init_with_allocator(item, message->_allocator);
                {
                    SynurangLiteReaderInternal value_reader;
                    sl_reader_init(&value_reader, value_data, value_len);
                    status = volvoxai_v1_id_stop_sequence_merge_reader(
                        item, &value_reader, message_depth + 1);
                }
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 6:
                if (!sl_read_float(
                        reader, wire_type, &message->field_temperature)) break;
                message->has_temperature = 1;
                break;
            case 7:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_top_k)) break;
                message->has_top_k = 1;
                break;
            case 8:
                if (!sl_read_float(
                        reader, wire_type, &message->field_top_p)) break;
                message->has_top_p = 1;
                break;
            case 9:
            {
                void* appended;
                if (wire_type == 2) {
                    const uint8_t* packed_data;
                    size_t packed_len;
                    SynurangLiteReaderInternal packed;
                    if (!sl_read_slice(reader, &packed_data, &packed_len)) break;
                    sl_reader_init(&packed, packed_data, packed_len);
                    while (packed.pos < packed.len) {
                        status = sl_array_append(
                            message->_allocator,
                            (void**)&message->field_eos_ids.data,
                            &message->field_eos_ids.len,
                            &message->field_eos_ids.cap,
                            sizeof(*message->field_eos_ids.data),
                            &appended);
                        if (status != SYNURANG_LITE_OK) return status;
                        if (!sl_read_int32_raw(
                                &packed,
                                (int32_t*)appended)) break;
                    }
                    if (packed.status != SYNURANG_LITE_OK || packed.pos != packed.len) {
                        reader->status = packed.status == SYNURANG_LITE_OK
                            ? SYNURANG_LITE_MALFORMED : packed.status;
                    }
                } else {
                    status = sl_array_append(
                        message->_allocator,
                        (void**)&message->field_eos_ids.data,
                        &message->field_eos_ids.len,
                        &message->field_eos_ids.cap,
                        sizeof(*message->field_eos_ids.data),
                        &appended);
                    if (status != SYNURANG_LITE_OK) return status;
                    if (!sl_read_int32(
                            reader,
                            wire_type,
                            (int32_t*)appended)) break;
                }
                break;
            }
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

