            case 5:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_rows_per_item)) break;
                break;
            case 6:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_useful_items)) break;
                break;
            case 7:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_useful_rows)) break;
                break;
