static SynurangLiteStatus volvoxai_v1_compilation_evidence_merge_reader(
    VolvoxaiV1CompilationEvidence* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
                if (!sl_read_enum(
                        reader, wire_type, &message->field_policy_mode)) break;
                break;
            case 2:
                if (!sl_read_enum(
                        reader, wire_type, &message->field_operator_fallback)) break;
                break;
            case 3:
            {
                const uint8_t* value_data;
                size_t value_len;
                VolvoxaiV1CompilationCandidate* item;
                void* appended;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = sl_array_append(
                    message->_allocator,
                    (void**)&message->field_candidates.data,
                    &message->field_candidates.len,
                    &message->field_candidates.cap,
                    sizeof(*message->field_candidates.data),
                    &appended);
                if (status != SYNURANG_LITE_OK) return status;
                item = (VolvoxaiV1CompilationCandidate*)appended;
                volvoxai_v1_compilation_candidate_init_with_allocator(item, message->_allocator);
                {
                    SynurangLiteReaderInternal value_reader;
                    sl_reader_init(&value_reader, value_data, value_len);
                    status = volvoxai_v1_compilation_candidate_merge_reader(
                        item, &value_reader, message_depth + 1);
                }
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 4:
                if (!sl_read_bool(
                        reader, wire_type, &message->field_tier_fallback_used)) break;
                break;
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

