VolvoxaiV1BatchWorkOutcome* volvoxai_v1_complete_batch_dispatch_request_add_outcomes(
    VolvoxaiV1CompleteBatchDispatchRequest* message) {
    const SynurangLiteAllocator* allocator;
    VolvoxaiV1BatchWorkOutcome* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_outcomes.len == message->field_outcomes.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_outcomes.cap ? message->field_outcomes.cap * 2u : 4u;
        if (capacity < message->field_outcomes.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (VolvoxaiV1BatchWorkOutcome*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_outcomes.len) {
            memcpy(grown, message->field_outcomes.data,
                   sizeof(*grown) * message->field_outcomes.len);
        }
        synurang_lite_release(allocator, message->field_outcomes.data);
        message->field_outcomes.data = grown;
        message->field_outcomes.cap = capacity;
    }
    {
        VolvoxaiV1BatchWorkOutcome* slot =
            &message->field_outcomes.data[message->field_outcomes.len];
        memset(slot, 0, sizeof(*slot));
        volvoxai_v1_batch_work_outcome_init_with_allocator(slot, allocator);
        message->field_outcomes.len++;
        return slot;
    }
}

