static SynurangLiteStatus volvoxai_v1_context_cache_state_merge_reader(
    VolvoxaiV1ContextCacheState* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
                if (!sl_read_bool(
                        reader, wire_type, &message->field_configured)) break;
                break;
            case 2:
                if (!sl_read_enum(
                        reader, wire_type, &message->field_policy)) break;
                break;
            case 3:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_page_tokens)) break;
                break;
            case 4:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_slot_token_capacity)) break;
                break;
            case 5:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_max_pages)) break;
                break;
            case 6:
            {
                const uint8_t* value_data;
                size_t value_len;
                VolvoxaiV1ContextCacheSlot* item;
                void* appended;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = sl_array_append(
                    message->_allocator,
                    (void**)&message->field_slots.data,
                    &message->field_slots.len,
                    &message->field_slots.cap,
                    sizeof(*message->field_slots.data),
                    &appended);
                if (status != SYNURANG_LITE_OK) return status;
                item = (VolvoxaiV1ContextCacheSlot*)appended;
                volvoxai_v1_context_cache_slot_init_with_allocator(item, message->_allocator);
                {
                    SynurangLiteReaderInternal value_reader;
                    sl_reader_init(&value_reader, value_data, value_len);
                    status = volvoxai_v1_context_cache_slot_merge_reader(
                        item, &value_reader, message_depth + 1);
                }
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 7:
            {
                void* appended;
                if (wire_type == 2) {
                    const uint8_t* packed_data;
                    size_t packed_len;
                    SynurangLiteReaderInternal packed;
                    if (!sl_read_slice(reader, &packed_data, &packed_len)) break;
                    sl_reader_init(&packed, packed_data, packed_len);
                    while (packed.pos < packed.len) {
                        status = sl_array_append(
                            message->_allocator,
                            (void**)&message->field_page_generations.data,
                            &message->field_page_generations.len,
                            &message->field_page_generations.cap,
                            sizeof(*message->field_page_generations.data),
                            &appended);
                        if (status != SYNURANG_LITE_OK) return status;
                        if (!sl_read_uint32_raw(
                                &packed,
                                (uint32_t*)appended)) break;
                    }
                    if (packed.status != SYNURANG_LITE_OK || packed.pos != packed.len) {
                        reader->status = packed.status == SYNURANG_LITE_OK
                            ? SYNURANG_LITE_MALFORMED : packed.status;
                    }
                } else {
                    status = sl_array_append(
                        message->_allocator,
                        (void**)&message->field_page_generations.data,
                        &message->field_page_generations.len,
                        &message->field_page_generations.cap,
                        sizeof(*message->field_page_generations.data),
                        &appended);
                    if (status != SYNURANG_LITE_OK) return status;
                    if (!sl_read_uint32(
                            reader,
                            wire_type,
                            (uint32_t*)appended)) break;
                }
                break;
            }
            case 8:
            {
                const uint8_t* value_data;
                size_t value_len;
                SynurangLiteBytes* item;
                void* appended;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = sl_array_append(
                    message->_allocator,
                    (void**)&message->field_tensors.data,
                    &message->field_tensors.len,
                    &message->field_tensors.cap,
                    sizeof(*message->field_tensors.data),
                    &appended);
                if (status != SYNURANG_LITE_OK) return status;
                item = (SynurangLiteBytes*)appended;
                status = synurang_lite_bytes_assign(
                    message->_allocator, item, value_data, value_len);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 9:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_logical_bytes)) break;
                break;
            case 10:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_resident_bytes)) break;
                break;
            case 11:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_reserved_bytes)) break;
                break;
            case 12:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_pool_bytes)) break;
                break;
            case 13:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_prefix_snapshot_bytes)) break;
                break;
            case 14:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_resident_pages)) break;
                break;
            case 15:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_reserved_pages)) break;
                break;
            case 16:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_free_pages)) break;
                break;
            case 17:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_shared_pages)) break;
                break;
            case 18:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_fragmentation_bytes)) break;
                break;
            case 19:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_high_water_pages)) break;
                break;
            case 20:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_prefix_hits)) break;
                break;
            case 21:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_prefix_misses)) break;
                break;
            case 22:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_copy_on_writes)) break;
                break;
            case 23:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_evictions)) break;
                break;
            case 24:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_allocation_failures)) break;
                break;
            case 25:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_cache_generation)) break;
                break;
            case 26:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (!message->field_report) {
                    message->field_report =
                        (VolvoxaiV1OperationReport*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_report));
                    if (!message->field_report) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_operation_report_init_with_allocator(
                        message->field_report, message->_allocator);
                }
                status = volvoxai_v1_operation_report_merge_at_depth(
                    message->field_report, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

