static SynurangLiteStatus volvoxai_v1_end_buffer_access_request_merge_reader(
    VolvoxaiV1EndBufferAccessRequest* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
            {
                void* appended;
                if (wire_type == 2) {
                    const uint8_t* packed_data;
                    size_t packed_len;
                    SynurangLiteReaderInternal packed;
                    if (!sl_read_slice(reader, &packed_data, &packed_len)) break;
                    sl_reader_init(&packed, packed_data, packed_len);
                    while (packed.pos < packed.len) {
                        status = sl_array_append(
                            message->_allocator,
                            (void**)&message->field_access_ids.data,
                            &message->field_access_ids.len,
                            &message->field_access_ids.cap,
                            sizeof(*message->field_access_ids.data),
                            &appended);
                        if (status != SYNURANG_LITE_OK) return status;
                        if (!sl_read_int64_raw(
                                &packed,
                                (int64_t*)appended)) break;
                    }
                    if (packed.status != SYNURANG_LITE_OK || packed.pos != packed.len) {
                        reader->status = packed.status == SYNURANG_LITE_OK
                            ? SYNURANG_LITE_MALFORMED : packed.status;
                    }
                } else {
                    status = sl_array_append(
                        message->_allocator,
                        (void**)&message->field_access_ids.data,
                        &message->field_access_ids.len,
                        &message->field_access_ids.cap,
                        sizeof(*message->field_access_ids.data),
                        &appended);
                    if (status != SYNURANG_LITE_OK) return status;
                    if (!sl_read_int64(
                            reader,
                            wire_type,
                            (int64_t*)appended)) break;
                }
                break;
            }
            case 2:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (!message->field_cuda) {
                    message->field_cuda =
                        (VolvoxaiV1CudaStreamCompletion*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_cuda));
                    if (!message->field_cuda) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_cuda_stream_completion_init_with_allocator(
                        message->field_cuda, message->_allocator);
                }
                status = volvoxai_v1_cuda_stream_completion_merge_at_depth(
                    message->field_cuda, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

SynurangLiteStatus volvoxai_v1_end_buffer_access_request_decode(
    VolvoxaiV1EndBufferAccessRequest* message,
    const uint8_t* data,
    size_t len) {
    VolvoxaiV1EndBufferAccessRequest temporary;
    SynurangLiteReaderInternal reader;
    SynurangLiteStatus status;
    if (!message || (!data && len != 0)) return SYNURANG_LITE_INVALID_ARGUMENT;
    volvoxai_v1_end_buffer_access_request_init_with_allocator(&temporary, message->_allocator);
    sl_reader_init(&reader, data, len);
    status = volvoxai_v1_end_buffer_access_request_merge_reader(&temporary, &reader, 0);
    if (status != SYNURANG_LITE_OK) {
        volvoxai_v1_end_buffer_access_request_free(&temporary);
        return status;
    }
    volvoxai_v1_end_buffer_access_request_free(message);
    *message = temporary;
    return SYNURANG_LITE_OK;
}
int64_t* volvoxai_v1_end_buffer_access_request_add_access_ids(
    VolvoxaiV1EndBufferAccessRequest* message) {
    const SynurangLiteAllocator* allocator;
    int64_t* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_access_ids.len == message->field_access_ids.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_access_ids.cap ? message->field_access_ids.cap * 2u : 4u;
        if (capacity < message->field_access_ids.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (int64_t*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_access_ids.len) {
            memcpy(grown, message->field_access_ids.data,
                   sizeof(*grown) * message->field_access_ids.len);
        }
        synurang_lite_release(allocator, message->field_access_ids.data);
        message->field_access_ids.data = grown;
        message->field_access_ids.cap = capacity;
    }
    {
        int64_t* slot =
            &message->field_access_ids.data[message->field_access_ids.len];
        memset(slot, 0, sizeof(*slot));
        message->field_access_ids.len++;
        return slot;
    }
}

