static SynurangLiteStatus volvoxai_v1_execution_budget_merge_reader(
    VolvoxaiV1ExecutionBudget* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_max_output_bytes)) break;
                message->has_max_output_bytes = 1;
                break;
            case 2:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_deadline_monotonic_ns)) break;
                message->has_deadline_monotonic_ns = 1;
                break;
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

SynurangLiteStatus volvoxai_v1_execution_budget_decode(
    VolvoxaiV1ExecutionBudget* message,
    const uint8_t* data,
    size_t len) {
    VolvoxaiV1ExecutionBudget temporary;
    SynurangLiteReaderInternal reader;
    SynurangLiteStatus status;
    if (!message || (!data && len != 0)) return SYNURANG_LITE_INVALID_ARGUMENT;
    volvoxai_v1_execution_budget_init_with_allocator(&temporary, message->_allocator);
    sl_reader_init(&reader, data, len);
    status = volvoxai_v1_execution_budget_merge_reader(&temporary, &reader, 0);
    if (status != SYNURANG_LITE_OK) {
        volvoxai_v1_execution_budget_free(&temporary);
        return status;
    }
    volvoxai_v1_execution_budget_free(message);
    *message = temporary;
    return SYNURANG_LITE_OK;
}

