VolvoxaiV1ExecutionRangeKind* volvoxai_v1_execution_entrypoint_add_allowed_ranges(
    VolvoxaiV1ExecutionEntrypoint* message) {
    const SynurangLiteAllocator* allocator;
    VolvoxaiV1ExecutionRangeKind* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_allowed_ranges.len == message->field_allowed_ranges.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_allowed_ranges.cap ? message->field_allowed_ranges.cap * 2u : 4u;
        if (capacity < message->field_allowed_ranges.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (VolvoxaiV1ExecutionRangeKind*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_allowed_ranges.len) {
            memcpy(grown, message->field_allowed_ranges.data,
                   sizeof(*grown) * message->field_allowed_ranges.len);
        }
        synurang_lite_release(allocator, message->field_allowed_ranges.data);
        message->field_allowed_ranges.data = grown;
        message->field_allowed_ranges.cap = capacity;
    }
    {
        VolvoxaiV1ExecutionRangeKind* slot =
            &message->field_allowed_ranges.data[message->field_allowed_ranges.len];
        memset(slot, 0, sizeof(*slot));
        message->field_allowed_ranges.len++;
        return slot;
    }
}
