            {
                void* appended;
                if (wire_type == 2) {
                    const uint8_t* packed_data;
                    size_t packed_len;
                    SynurangLiteReaderInternal packed;
                    if (!sl_read_slice(reader, &packed_data, &packed_len)) break;
                    sl_reader_init(&packed, packed_data, packed_len);
                    while (packed.pos < packed.len) {
                        status = sl_array_append(
                            message->_allocator,
                            (void**)&message->field_outputs.data,
                            &message->field_outputs.len,
                            &message->field_outputs.cap,
                            sizeof(*message->field_outputs.data),
                            &appended);
                        if (status != SYNURANG_LITE_OK) return status;
                        if (!sl_read_uint32_raw(
                                &packed,
                                (uint32_t*)appended)) break;
                    }
                    if (packed.status != SYNURANG_LITE_OK || packed.pos != packed.len) {
                        reader->status = packed.status == SYNURANG_LITE_OK
                            ? SYNURANG_LITE_MALFORMED : packed.status;
                    }
                } else {
                    status = sl_array_append(
                        message->_allocator,
                        (void**)&message->field_outputs.data,
                        &message->field_outputs.len,
                        &message->field_outputs.cap,
                        sizeof(*message->field_outputs.data),
                        &appended);
                    if (status != SYNURANG_LITE_OK) return status;
                    if (!sl_read_uint32(
                            reader,
                            wire_type,
                            (uint32_t*)appended)) break;
                }
                break;
            }
            case 6:
                if (!sl_read_bool(
                        reader, wire_type, &message->field_skipped)) break;
                break;
            case 7:
                if (!sl_read_bool(
                        reader, wire_type, &message->field_fused)) break;
                break;
            case 8:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (!message->field_cost) {
                    message->field_cost =
                        (VolvoxaiV1StepCost*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_cost));
                    if (!message->field_cost) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_step_cost_init_with_allocator(
                        message->field_cost, message->_allocator);
                }
                status = volvoxai_v1_step_cost_merge_at_depth(
                    message->field_cost, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 9:
                if (!sl_read_enum(
                        reader, wire_type, &message->field_phase)) break;
