static SynurangLiteStatus volvoxai_v1_execution_scope_merge_reader(
    VolvoxaiV1ExecutionScope* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = synurang_lite_bytes_assign(
                    message->_allocator,
                    &message->field_entrypoint,
                    value_data,
                    value_len);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 2:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (message->which_range != 2) {
                    volvoxai_v1_execution_scope_clear_range(message);
                }
                if (!message->field_full) {
                    message->field_full =
                        (VolvoxaiV1Empty*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_full));
                    if (!message->field_full) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_empty_init_with_allocator(
                        message->field_full, message->_allocator);
                }
                status = volvoxai_v1_empty_merge_at_depth(
                    message->field_full, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                message->which_range = 2;
                break;
            }
            case 3:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (message->which_range != 3) {
                    volvoxai_v1_execution_scope_clear_range(message);
                }
                if (!message->field_prefix_rows) {
                    message->field_prefix_rows =
                        (VolvoxaiV1PrefixRows*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_prefix_rows));
                    if (!message->field_prefix_rows) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_prefix_rows_init_with_allocator(
                        message->field_prefix_rows, message->_allocator);
                }
                status = volvoxai_v1_prefix_rows_merge_at_depth(
                    message->field_prefix_rows, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                message->which_range = 3;
                break;
            }
            case 4:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (message->which_range != 4) {
                    volvoxai_v1_execution_scope_clear_range(message);
                }
                if (!message->field_slot_rows) {
                    message->field_slot_rows =
                        (VolvoxaiV1SlotRows*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_slot_rows));
                    if (!message->field_slot_rows) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_slot_rows_init_with_allocator(
                        message->field_slot_rows, message->_allocator);
                }
                status = volvoxai_v1_slot_rows_merge_at_depth(
                    message->field_slot_rows, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                message->which_range = 4;
                break;
            }
            case 5:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (message->which_range != 5) {
                    volvoxai_v1_execution_scope_clear_range(message);
                }
                if (!message->field_dependencies) {
                    message->field_dependencies =
                        (VolvoxaiV1DependencyClosure*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_dependencies));
                    if (!message->field_dependencies) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_dependency_closure_init_with_allocator(
                        message->field_dependencies, message->_allocator);
                }
                status = volvoxai_v1_dependency_closure_merge_at_depth(
                    message->field_dependencies, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                message->which_range = 5;
                break;
            }
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

