SynurangLiteBytes* volvoxai_v1_full_prefix_generation_contract_add_zero_append_inputs(
    VolvoxaiV1FullPrefixGenerationContract* message) {
    const SynurangLiteAllocator* allocator;
    SynurangLiteBytes* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_zero_append_inputs.len == message->field_zero_append_inputs.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_zero_append_inputs.cap ? message->field_zero_append_inputs.cap * 2u : 4u;
        if (capacity < message->field_zero_append_inputs.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (SynurangLiteBytes*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_zero_append_inputs.len) {
            memcpy(grown, message->field_zero_append_inputs.data,
                   sizeof(*grown) * message->field_zero_append_inputs.len);
        }
        synurang_lite_release(allocator, message->field_zero_append_inputs.data);
        message->field_zero_append_inputs.data = grown;
        message->field_zero_append_inputs.cap = capacity;
    }
    {
        SynurangLiteBytes* slot =
            &message->field_zero_append_inputs.data[message->field_zero_append_inputs.len];
        memset(slot, 0, sizeof(*slot));
        message->field_zero_append_inputs.len++;
        return slot;
    }
}

