static SynurangLiteStatus volvoxai_v1_generate_request_merge_reader(
    VolvoxaiV1GenerateRequest* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
                if (!sl_read_int64(
                        reader, wire_type, &message->field_context_id)) break;
                break;
            case 2:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (!message->field_initial_inputs) {
                    message->field_initial_inputs =
                        (VolvoxaiV1GenerationInputs*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_initial_inputs));
                    if (!message->field_initial_inputs) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_generation_inputs_init_with_allocator(
                        message->field_initial_inputs, message->_allocator);
                }
                status = volvoxai_v1_generation_inputs_merge_at_depth(
                    message->field_initial_inputs, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 3:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (!message->field_budget) {
                    message->field_budget =
                        (VolvoxaiV1GenerationBudget*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_budget));
                    if (!message->field_budget) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_generation_budget_init_with_allocator(
                        message->field_budget, message->_allocator);
                }
                status = volvoxai_v1_generation_budget_merge_at_depth(
                    message->field_budget, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 4:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (!message->field_outputs) {
                    message->field_outputs =
                        (VolvoxaiV1OutputOptions*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_outputs));
                    if (!message->field_outputs) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_output_options_init_with_allocator(
                        message->field_outputs, message->_allocator);
                }
                status = volvoxai_v1_output_options_merge_at_depth(
                    message->field_outputs, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

