static SynurangLiteStatus volvoxai_v1_get_resource_snapshot_request_merge_reader(
    VolvoxaiV1GetResourceSnapshotRequest* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (message->which_scope != 1) {
                    volvoxai_v1_get_resource_snapshot_request_clear_scope(message);
                }
                if (!message->field_module) {
                    message->field_module =
                        (VolvoxaiV1Empty*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_module));
                    if (!message->field_module) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_empty_init_with_allocator(
                        message->field_module, message->_allocator);
                }
                status = volvoxai_v1_empty_merge_at_depth(
                    message->field_module, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                message->which_scope = 1;
                break;
            }
            case 2:
                if (message->which_scope != 2) {
                    volvoxai_v1_get_resource_snapshot_request_clear_scope(message);
                }
                if (!sl_read_int64(
                        reader, wire_type, &message->field_runtime_id)) break;
                message->which_scope = 2;
                break;
            case 3:
                if (message->which_scope != 3) {
                    volvoxai_v1_get_resource_snapshot_request_clear_scope(message);
                }
                if (!sl_read_int64(
                        reader, wire_type, &message->field_context_id)) break;
                message->which_scope = 3;
                break;
            case 4:
                if (!sl_read_bool(
                        reader, wire_type, &message->field_include_device)) break;
                break;
            case 5:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_max_allocations)) break;
                message->has_max_allocations = 1;
                break;
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

