SynurangLiteBytes* volvoxai_v1_input_bindings_add_reuse(
    VolvoxaiV1InputBindings* message) {
    const SynurangLiteAllocator* allocator;
    SynurangLiteBytes* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_reuse.len == message->field_reuse.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_reuse.cap ? message->field_reuse.cap * 2u : 4u;
        if (capacity < message->field_reuse.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (SynurangLiteBytes*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_reuse.len) {
            memcpy(grown, message->field_reuse.data,
                   sizeof(*grown) * message->field_reuse.len);
        }
        synurang_lite_release(allocator, message->field_reuse.data);
        message->field_reuse.data = grown;
        message->field_reuse.cap = capacity;
    }
    {
        SynurangLiteBytes* slot =
            &message->field_reuse.data[message->field_reuse.len];
        memset(slot, 0, sizeof(*slot));
        message->field_reuse.len++;
        return slot;
    }
}
