static SynurangLiteStatus volvoxai_v1_memory_bound_proof_merge_reader(
    VolvoxaiV1MemoryBoundProof* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = synurang_lite_bytes_assign(
                    message->_allocator,
                    &message->field_budget_domain_id,
                    value_data,
                    value_len);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 2:
                if (!sl_read_enum(
                        reader, wire_type, &message->field_kind)) break;
                break;
            case 3:
            {
                const uint8_t* value_data;
                size_t value_len;
                VolvoxaiV1MemoryPeakCase* item;
                void* appended;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = sl_array_append(
                    message->_allocator,
                    (void**)&message->field_cases.data,
                    &message->field_cases.len,
                    &message->field_cases.cap,
                    sizeof(*message->field_cases.data),
                    &appended);
                if (status != SYNURANG_LITE_OK) return status;
                item = (VolvoxaiV1MemoryPeakCase*)appended;
                volvoxai_v1_memory_peak_case_init_with_allocator(item, message->_allocator);
                {
                    SynurangLiteReaderInternal value_reader;
                    sl_reader_init(&value_reader, value_data, value_len);
                    status = volvoxai_v1_memory_peak_case_merge_reader(
                        item, &value_reader, message_depth + 1);
                }
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 4:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (!message->field_maximum_bytes) {
                    message->field_maximum_bytes =
                        (VolvoxaiV1MemoryByteSize*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_maximum_bytes));
                    if (!message->field_maximum_bytes) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_memory_byte_size_init_with_allocator(
                        message->field_maximum_bytes, message->_allocator);
                }
                status = volvoxai_v1_memory_byte_size_merge_at_depth(
                    message->field_maximum_bytes, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 5:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (!message->field_limit_bytes) {
                    message->field_limit_bytes =
                        (VolvoxaiV1MemoryByteSize*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_limit_bytes));
                    if (!message->field_limit_bytes) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_memory_byte_size_init_with_allocator(
                        message->field_limit_bytes, message->_allocator);
                }
                status = volvoxai_v1_memory_byte_size_merge_at_depth(
                    message->field_limit_bytes, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

