VolvoxaiV1MemoryPeakCase* volvoxai_v1_memory_bound_proof_add_cases(
    VolvoxaiV1MemoryBoundProof* message) {
    const SynurangLiteAllocator* allocator;
    VolvoxaiV1MemoryPeakCase* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_cases.len == message->field_cases.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_cases.cap ? message->field_cases.cap * 2u : 4u;
        if (capacity < message->field_cases.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (VolvoxaiV1MemoryPeakCase*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_cases.len) {
            memcpy(grown, message->field_cases.data,
                   sizeof(*grown) * message->field_cases.len);
        }
        synurang_lite_release(allocator, message->field_cases.data);
        message->field_cases.data = grown;
        message->field_cases.cap = capacity;
    }
    {
        VolvoxaiV1MemoryPeakCase* slot =
            &message->field_cases.data[message->field_cases.len];
        memset(slot, 0, sizeof(*slot));
        volvoxai_v1_memory_peak_case_init_with_allocator(slot, allocator);
        message->field_cases.len++;
        return slot;
    }
}

