VolvoxaiV1ExecutionEntrypoint* volvoxai_v1_model_execution_contract_add_entrypoints(
    VolvoxaiV1ModelExecutionContract* message) {
    const SynurangLiteAllocator* allocator;
    VolvoxaiV1ExecutionEntrypoint* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_entrypoints.len == message->field_entrypoints.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_entrypoints.cap ? message->field_entrypoints.cap * 2u : 4u;
        if (capacity < message->field_entrypoints.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (VolvoxaiV1ExecutionEntrypoint*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_entrypoints.len) {
            memcpy(grown, message->field_entrypoints.data,
                   sizeof(*grown) * message->field_entrypoints.len);
        }
        synurang_lite_release(allocator, message->field_entrypoints.data);
        message->field_entrypoints.data = grown;
        message->field_entrypoints.cap = capacity;
    }
    {
        VolvoxaiV1ExecutionEntrypoint* slot =
            &message->field_entrypoints.data[message->field_entrypoints.len];
        memset(slot, 0, sizeof(*slot));
        volvoxai_v1_execution_entrypoint_init_with_allocator(slot, allocator);
        message->field_entrypoints.len++;
        return slot;
    }
}
