static SynurangLiteStatus volvoxai_v1_model_source_options_merge_reader(
    VolvoxaiV1ModelSourceOptions* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_max_total_bytes)) break;
                break;
            case 2:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_max_shard_bytes)) break;
                break;
            case 3:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (!message->field_graph) {
                    message->field_graph =
                        (VolvoxaiV1ModelSourceIntegrity*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_graph));
                    if (!message->field_graph) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_model_source_integrity_init_with_allocator(
                        message->field_graph, message->_allocator);
                }
                status = volvoxai_v1_model_source_integrity_merge_at_depth(
                    message->field_graph, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 4:
            {
                const uint8_t* value_data;
                size_t value_len;
                VolvoxaiV1ModelSourceIntegrity* item;
                void* appended;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = sl_array_append(
                    message->_allocator,
                    (void**)&message->field_weight_shards.data,
                    &message->field_weight_shards.len,
                    &message->field_weight_shards.cap,
                    sizeof(*message->field_weight_shards.data),
                    &appended);
                if (status != SYNURANG_LITE_OK) return status;
                item = (VolvoxaiV1ModelSourceIntegrity*)appended;
                volvoxai_v1_model_source_integrity_init_with_allocator(item, message->_allocator);
                {
                    SynurangLiteReaderInternal value_reader;
                    sl_reader_init(&value_reader, value_data, value_len);
                    status = volvoxai_v1_model_source_integrity_merge_reader(
                        item, &value_reader, message_depth + 1);
                }
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

