SynurangLiteBytes* volvoxai_v1_platform_info_add_compiled_backends(
    VolvoxaiV1PlatformInfo* message) {
    const SynurangLiteAllocator* allocator;
    SynurangLiteBytes* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_compiled_backends.len == message->field_compiled_backends.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_compiled_backends.cap ? message->field_compiled_backends.cap * 2u : 4u;
        if (capacity < message->field_compiled_backends.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (SynurangLiteBytes*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_compiled_backends.len) {
            memcpy(grown, message->field_compiled_backends.data,
                   sizeof(*grown) * message->field_compiled_backends.len);
        }
        synurang_lite_release(allocator, message->field_compiled_backends.data);
        message->field_compiled_backends.data = grown;
        message->field_compiled_backends.cap = capacity;
    }
    {
        SynurangLiteBytes* slot =
            &message->field_compiled_backends.data[message->field_compiled_backends.len];
        memset(slot, 0, sizeof(*slot));
        message->field_compiled_backends.len++;
        return slot;
    }
}

