static SynurangLiteStatus volvoxai_v1_shape_plan_evidence_merge_reader(
    VolvoxaiV1ShapePlanEvidence* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
                if (!sl_read_fixed64(
                        reader, wire_type, &message->field_signature_digest)) break;
                break;
            case 2:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = synurang_lite_bytes_assign(
                    message->_allocator,
                    &message->field_signature,
                    value_data,
                    value_len);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 3:
                if (!sl_read_enum(
                        reader, wire_type, &message->field_origin)) break;
                break;
            case 4:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_bind_time_ns)) break;
                break;
            case 5:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_logical_bytes)) break;
                break;
            case 6:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_arena_required_bytes)) break;
                break;
            case 7:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_arena_capacity_bytes)) break;
                break;
            case 8:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_arena_high_water_bytes)) break;
                break;
            case 9:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_arena_grow_count)) break;
                break;
            case 10:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_resource_generation)) break;
                break;
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

