static SynurangLiteStatus volvoxai_v1_slot_row_merge_reader(
    VolvoxaiV1SlotRow* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
                if (message->which_action != 1) {
                    volvoxai_v1_slot_row_clear_action(message);
                }
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_position)) break;
                message->which_action = 1;
                break;
            case 2:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (message->which_action != 2) {
                    volvoxai_v1_slot_row_clear_action(message);
                }
                if (!message->field_recompute) {
                    message->field_recompute =
                        (VolvoxaiV1Empty*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_recompute));
                    if (!message->field_recompute) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_empty_init_with_allocator(
                        message->field_recompute, message->_allocator);
                }
                status = volvoxai_v1_empty_merge_at_depth(
                    message->field_recompute, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                message->which_action = 2;
                break;
            }
            case 3:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (message->which_action != 3) {
                    volvoxai_v1_slot_row_clear_action(message);
                }
                if (!message->field_empty) {
                    message->field_empty =
                        (VolvoxaiV1Empty*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_empty));
                    if (!message->field_empty) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_empty_init_with_allocator(
                        message->field_empty, message->_allocator);
                }
                status = volvoxai_v1_empty_merge_at_depth(
                    message->field_empty, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                message->which_action = 3;
                break;
            }
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

