VolvoxaiV1Tensor* volvoxai_v1_stateless_batch_work_add_inputs(
    VolvoxaiV1StatelessBatchWork* message) {
    const SynurangLiteAllocator* allocator;
    VolvoxaiV1Tensor* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_inputs.len == message->field_inputs.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_inputs.cap ? message->field_inputs.cap * 2u : 4u;
        if (capacity < message->field_inputs.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (VolvoxaiV1Tensor*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_inputs.len) {
            memcpy(grown, message->field_inputs.data,
                   sizeof(*grown) * message->field_inputs.len);
        }
        synurang_lite_release(allocator, message->field_inputs.data);
        message->field_inputs.data = grown;
        message->field_inputs.cap = capacity;
    }
    {
        VolvoxaiV1Tensor* slot =
            &message->field_inputs.data[message->field_inputs.len];
        memset(slot, 0, sizeof(*slot));
        volvoxai_v1_tensor_init_with_allocator(slot, allocator);
        message->field_inputs.len++;
        return slot;
    }
}

