VolvoxaiV1TraceDeviceCoverage* volvoxai_v1_trace_info_add_devices(
    VolvoxaiV1TraceInfo* message) {
    const SynurangLiteAllocator* allocator;
    VolvoxaiV1TraceDeviceCoverage* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_devices.len == message->field_devices.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_devices.cap ? message->field_devices.cap * 2u : 4u;
        if (capacity < message->field_devices.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (VolvoxaiV1TraceDeviceCoverage*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_devices.len) {
            memcpy(grown, message->field_devices.data,
                   sizeof(*grown) * message->field_devices.len);
        }
        synurang_lite_release(allocator, message->field_devices.data);
        message->field_devices.data = grown;
        message->field_devices.cap = capacity;
    }
    {
        VolvoxaiV1TraceDeviceCoverage* slot =
            &message->field_devices.data[message->field_devices.len];
        memset(slot, 0, sizeof(*slot));
        volvoxai_v1_trace_device_coverage_init_with_allocator(slot, allocator);
        message->field_devices.len++;
        return slot;
    }
}
