static SynurangLiteStatus volvoxai_v1_wasm_memory_snapshot_merge_reader(
    VolvoxaiV1WasmMemorySnapshot* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
                if (!sl_read_enum(
                        reader, wire_type, &message->field_status)) break;
                break;
            case 2:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_linear_bytes)) break;
                break;
            case 3:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_allocated_bytes)) break;
                break;
            case 4:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_free_bytes)) break;
                break;
            case 5:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_allocator_metadata_bytes)) break;
                break;
            case 6:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_module_prefix_bytes)) break;
                break;
            case 7:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_page_slack_bytes)) break;
                break;
            case 8:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_largest_free_block_bytes)) break;
                break;
            case 9:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_allocated_blocks)) break;
                break;
            case 10:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_free_blocks)) break;
                break;
            case 11:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_untracked_bytes)) break;
                break;
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

